export async function listTools() {
  return [
    {
      name: 'run_with_progress',
      description: 'Run a task and report progress from 0 to 1',
      inputSchema: {
        type: 'object',
        properties: {
          steps: {
            type: 'integer',
            minimum: 1,
            description: 'Number of progress steps (positive integer)'
          }
        },
        required: ['steps']
      }
    }
  ];
}

export async function callTool(name, args = {}, options = {}) {
  if (name !== 'run_with_progress') {
    const error = new Error('Tool not found');
    error.code = -32601;
    throw error;
  }
  const steps = args.steps;
  if (!Number.isInteger(steps) || steps < 1) {
    const error = new Error('steps must be a positive integer');
    error.code = -32602;
    throw error;
  }
  const onProgress = options.onProgress;
  if (typeof onProgress === 'function') {
    onProgress(0);
    for (let i = 1; i <= steps; i++) {
      onProgress(i / steps);
    }
  }
  return {
    content: [{ type: 'text', text: 'completed' }]
  };
}
